css:
/* ==========================================================================
   海报墙 · Folia Poster Wall
   1:1 复刻 Folia（folia-major）的主题语言，不再迁就 MyTranscript 的骨架：
   近黑底 + 双色光晕 + 胶片噪点 + 无缝海报瓦片 + 悬浮胶囊播放条。
   取值全部来自 Folia 安装包内 CSS（Lattice / wall / BravaisStage）。
   ========================================================================== */

html[data-theme] {
  --bg: #070708;
  --ink: #f7f4ee;
  --bright: #ffffff;
  --muted: rgba(247, 244, 238, 0.62);
  --dim: rgba(247, 244, 238, 0.38);
  --accent: #fd5c47;
  --accent2: #6a48ff;
  --accent-ink: #fd5c47;
  --panel: rgba(255, 255, 255, 0.045);
  --panel2: rgba(255, 255, 255, 0.07);
  --hover: rgba(255, 255, 255, 0.06);
  --line: rgba(255, 255, 255, 0.10);
  --line2: rgba(255, 255, 255, 0.055);
  --coverbg: #101014;
  --serif: system-ui, -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  --sans: system-ui, -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  --mono: ui-monospace, "SF Mono", Consolas, monospace;
  --ease: cubic-bezier(0.22, 0.61, 0.36, 1);
  /* 侧栏 / 搜索胶囊 / 悬浮底栏共用一层烟熏玻璃：同色、同模糊、同描边。 */
  --folia-glass: rgba(18, 18, 20, 0.62);
  --folia-glass-line: rgba(255, 255, 255, 0.10);
  --folia-glass-blur: blur(18px) saturate(1.1);
  --folia-glass-shadow: 0 24px 60px rgba(0, 0, 0, 0.52);
  /* 字幕页不再用纯黑：暖炭底 + 顶部一点专辑色余温，和珊瑚主色同一族 */
  --folia-player-bg: #0d0b09;
  --folia-player-glow: #2a1a12;
}

/* ---------- 0. 画布：底色 + 两团光晕 + 噪点 + 暗角 ---------- */
html[data-theme] body,
html[data-theme] .app {
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
}

html[data-theme] body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 14% 12%, color-mix(in srgb, var(--accent) 16%, transparent), transparent 29%),
    radial-gradient(circle at 86% 82%, color-mix(in srgb, var(--accent2) 20%, transparent), transparent 32%);
}

html[data-theme] body::after {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 9999;
  pointer-events: none;
  opacity: 0.13;
  mix-blend-mode: soft-light;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.92' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.55'/%3E%3C/svg%3E");
}

html[data-theme] .app {
  background:
    radial-gradient(circle at 14% 12%, color-mix(in srgb, var(--accent) 16%, transparent), transparent 29%),
    radial-gradient(circle at 86% 82%, color-mix(in srgb, var(--accent2) 20%, transparent), transparent 32%),
    var(--bg);
  box-shadow: inset 0 0 120px 40px rgba(0, 0, 0, 0.55);
}

/* ---------- 1. 骨架：侧栏整条隐藏，只留一个悬浮钮 ---------- */
html[data-theme] .app { display: block; }

/* 侧栏 = 贴在左缘、垂直居中的圆角浮条（不是通高柱子） */
html[data-theme] .sidebar {
  position: fixed;
  left: 14px;
  top: 50%;
  bottom: auto;
  width: 64px;
  height: auto;
  max-height: 82vh;
  z-index: 70;
  padding: 10px 7px;
  border: 1px solid var(--folia-glass-line);
  border-radius: 22px;
  background: var(--folia-glass);
  box-shadow: var(--folia-glass-shadow), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  backdrop-filter: var(--folia-glass-blur);
  -webkit-backdrop-filter: var(--folia-glass-blur);
  overflow: auto;
  scrollbar-width: none;
  transform: translate(-120%, -50%);
  opacity: 0;
  pointer-events: none;
  transition: width var(--motion-slow) var(--ease), height var(--motion-slow) var(--ease),
    left var(--motion-slow) var(--ease), padding var(--motion-slow) var(--ease),
    border-radius var(--motion-slow) var(--ease), transform var(--motion-slow) var(--ease),
    opacity var(--motion-slow) var(--ease);
}
html[data-theme] .sidebar::-webkit-scrollbar { width: 0; height: 0; }
/* 默认收起；点悬浮钮展开（body 去掉 nav-collapsed）就滑出这支浮条 */
html[data-theme] body:not(.nav-collapsed) .sidebar {
  display: flex;
  transform: translate(0, -50%);
  opacity: 1;
  pointer-events: auto;
}

html[data-theme] .brand {
  justify-content: center;
  gap: 0;
  padding: 2px 0 8px;
}
html[data-theme] .brand > div:not(.brand-mark) { display: none; }
html[data-theme] .brand-name,
html[data-theme] .brand-sub,
html[data-theme] .nav-label,
html[data-theme] .sidebar-add,
html[data-theme] .mobile-more-close,
html[data-theme] .plugin-slot,
html[data-theme] #pluginNavLabel,
html[data-theme] #pluginNav { display: none !important; }

html[data-theme] .brand-mark {
  width: 34px;
  height: 34px;
  border: 1px solid rgba(255, 255, 255, 0.10);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  color: var(--ink);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}
html[data-theme] .brand-mark svg { width: 16px; height: 16px; fill: none; stroke: var(--ink); }

html[data-theme] .nav {
  display: flex;
  flex-direction: column;
  gap: 3px;
  align-items: center;
}
/* 两组导航之间用一道极淡的分隔线断开，不再是一根没有呼吸的图标柱子 */
html[data-theme] #sideNav2 {
  margin-top: 7px;
  padding-top: 7px;
  border-top: 1px solid rgba(255, 255, 255, 0.07);
}

html[data-theme] .nav button {
  width: 38px;
  height: 38px;
  padding: 0;
  border: 0;
  border-radius: 999px;
  justify-content: center;
  font-size: 0;
  color: rgba(247, 244, 238, 0.60);
  background: transparent;
  transition: background-color var(--motion-normal) var(--ease), color var(--motion-normal) var(--ease), scale var(--motion-fast) var(--ease);
}
html[data-theme] .nav button:hover { background: rgba(255, 255, 255, 0.08); color: var(--ink); }
html[data-theme] .nav button:hover svg { scale: 1.06; }
html[data-theme] .nav button svg { transition: scale var(--motion-fast) var(--ease); }
/* 图标栏只剩图标：悬停时从右侧浮出功能名（Folia 的 rail tooltip） */
html[data-theme] .sidebar { overflow: visible; }
html[data-theme] .sidebar .nav button { position: relative; }
html[data-theme] .sidebar .nav button::after {
  content: attr(data-label);
  position: absolute;
  left: calc(100% + 12px);
  top: 50%;
  translate: -4px -50%;
  padding: 7px 11px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 10px;
  background: rgba(10, 10, 12, 0.92);
  box-shadow: 0 10px 26px rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(10px);
  color: var(--ink);
  font: 700 11px/1 var(--sans);
  letter-spacing: 0.04em;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--motion-fast) var(--ease), translate var(--motion-fast) var(--ease);
}
html[data-theme] .sidebar .nav button:hover::after,
html[data-theme] .sidebar .nav button:focus::after,
html[data-theme] .sidebar .nav button:focus-visible::after {
  opacity: 1;
  translate: 0 -50%;
}
html[data-theme] .nav button.active,
html[data-theme] .nav button[aria-current="page"] {
  border: 0;
  outline: 0;
  background: color-mix(in srgb, var(--accent) 18%, transparent);
  color: var(--bright);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 34%, transparent);
}
html[data-theme] .nav .nav-ico,
html[data-theme] .nav button svg {
  width: 15px;
  height: 15px;
  flex: 0 0 15px;
  padding: 0;
  border-radius: 0;
  background: transparent !important;
}
html[data-theme] .nav button:hover .nav-ico { background: transparent !important; }

html[data-theme] .sidebar-bottom { display: none; }

/* ---------- 2. 顶栏：平时看不见，鼠标贴到屏幕顶端才浮出来 ---------- */
html[data-theme] .main {
  padding: 0 0 110px;
  height: 100vh;
  overflow: auto;
  scroll-padding-top: 20px;
}
/* 基础层的 .page 有 1480px 上限并在大屏居中，全屏后两侧就留出黑边；墙要一路铺到窗口边缘 */
html[data-theme] .page {
  max-width: none;
  margin: 0;
}
/* 播放中的那张小播放条和底栏会同时出现（两条底栏），主题里只留一条 */
html[data-theme] .mini-player { display: none !important; }

/* 顶端 18px 是感应区；贴上去才显示右侧两个圆钮 */
html[data-theme] .topbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 18px;
  padding: 0;
  margin: 0;
  border: 0;
  background: transparent;
  backdrop-filter: none;
  justify-content: flex-end;
  align-items: flex-start;
  overflow: visible;
  pointer-events: auto;
  z-index: 92;
}
html[data-theme] .topbar:hover { height: 62px; }

html[data-theme] .topbar .crumb { display: contents; }
html[data-theme] .topbar .crumb b { display: none; }
/* Folia 的侧栏常驻，用自动隐藏和左缘唤回就够了，不再保留手动收起钮。 */
html[data-theme] .topbar .rail-toggle { display: none; }

html[data-theme] .topbar .top-actions {
  position: absolute;
  top: 12px;
  right: 14px;
  gap: 8px;
  opacity: 0;
  transform: translateY(-6px);
  transition: opacity var(--motion-slow) var(--ease), transform var(--motion-slow) var(--ease);
  pointer-events: none;
}
html[data-theme] .topbar:hover .top-actions,
html[data-theme] .topbar .top-actions:focus-within {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}
html[data-theme] .top-actions > button,
html[data-theme] .top-actions .btn {
  width: 40px;
  height: 40px;
  min-width: 40px;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--ink);
  display: grid;
  place-items: center;
  font-size: 0;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.24);
  backdrop-filter: blur(8px);
}
html[data-theme] .top-actions > button:hover { background: rgba(255, 255, 255, 0.14); }
html[data-theme] .top-actions svg,
html[data-theme] .top-actions .btn-ico { width: 16px; height: 16px; }

/* ---------- 3. 首页：只剩一面墙 ---------- */
html[data-theme] .ledger-home {
  max-width: none;
  margin: 0;
  padding: 0;
}

html[data-theme] .ledger-home .ledger-mast {
  display: block;
  padding: 0;
  margin: 0;
  border: 0;
}
html[data-theme] .ledger-home .ledger-mast-copy { display: contents; }
html[data-theme] .ledger-home .ledger-mast-copy > .eyebrow,
html[data-theme] .ledger-home .ledger-mast-copy > h1,
html[data-theme] .ledger-home .ledger-mast-copy > p,
html[data-theme] .ledger-home .ledger-editor,
html[data-theme] .ledger-home .ledger-rule,
html[data-theme] .ledger-home .ledger-section,
html[data-theme] .ledger-home #homeContinue,
html[data-theme] .ledger-home #homeRecent,
html[data-theme] .ledger-home #homeStats,
html[data-theme] .ledger-home .home-onboard { display: none !important; }
/* 推荐墙本身就是首页：包着 #homeRecommended 的那一节必须留着，
   其余 ledger 分节（继续收听 / 最近更新 / 统计）全部让位。 */
html[data-theme] .ledger-home .ledger-section:has(#homeRecommended) { display: block !important; }
html[data-theme] .ledger-home .ledger-section:has(#homeRecommended) > h3,
html[data-theme] .ledger-home .ledger-section:has(#homeRecommended) > small { display: none !important; }

/* 搜索：Folia 顶部悬浮胶囊 */
html[data-theme] .ledger-search {
  position: fixed;
  z-index: 40;
  top: 14px;
  left: 50%;
  transform: translateX(-50%);
  width: min(520px, 52vw);
  max-width: none;
  height: 42px;
  padding: 0 6px 0 16px;
  gap: 8px;
  border: 1px solid var(--folia-glass-line);
  border-radius: 999px;
  background: var(--folia-glass);
  backdrop-filter: var(--folia-glass-blur);
  -webkit-backdrop-filter: var(--folia-glass-blur);
  box-shadow: var(--folia-glass-shadow);
  opacity: 1;
  translate: 0 0;
  transition: opacity var(--motion-normal) var(--ease), translate var(--motion-normal) var(--ease),
    top var(--motion-slow) var(--ease),
    width var(--motion-slow) var(--ease), height var(--motion-slow) var(--ease),
    padding var(--motion-slow) var(--ease), background-color var(--motion-fast) var(--ease);
}
html[data-theme] .ledger-search span { color: rgba(247, 244, 238, 0.5); display: grid; place-items: center; }
html[data-theme] .ledger-search input {
  font: 500 13.5px/1 var(--sans);
  color: var(--ink);
  letter-spacing: 0.01em;
}
html[data-theme] .ledger-search input::placeholder { color: rgba(247, 244, 238, 0.42); }
html[data-theme] .ledger-search button {
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.10);
  color: var(--ink);
}
html[data-theme] .ledger-search button:hover { background: var(--accent); color: #fff; }

/* ---------- 4. 海报墙：大小混排、无缝、无边框 ---------- */
/* 首页整页就是墙：不留左右白，瓦片一路铺到屏幕边缘，往下滚不完 */
html[data-theme] #page-home { padding: 0; }

/* 二维墙：三块同宽 12 栏块并排；横向位置由 JS 的 --folia-block-w / left 控制，
   镜头用 .main 的 scrollLeft，走到边上时整列倒到另一头，实现 Folia 的横向无限。 */
html[data-theme] .folia-wall-plane {
  position: relative;
  width: calc(var(--folia-block-w, 100vw) * 3);
  margin: 0;
  padding: 0;
}
html[data-theme] .folia-wall-plane > #homeRecommended {
  position: absolute;
  top: 0;
  width: var(--folia-block-w, 100vw);
  margin: 0;
}
/* 墙是相机：拖拽平移（bindWallDragPan），拖动时给 grabbing 并关掉选区 */
html[data-theme] .main.is-panning { cursor: grabbing; user-select: none; }

html[data-theme] #homeRecommended {
  counter-reset: folia-poster;
  container-type: inline-size;
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  grid-auto-rows: calc((100cqw - 22px) / 12);
  grid-auto-flow: dense;
  gap: 2px;
  margin: 0;
  padding: 0 0 128px;   /* 顶上不留黑边：第一排瓦片直接接到窗口顶，顶栏浮在上面 */
  height: auto;
  background: transparent;
}
/* 无限墙 = Folia 的 12×8 方块格：一块 = 12 栏 × 8 行、12 席严格铺满 96 格。
   具体落格由 JS 的模板块（BLOCK_TEMPLATES）写内联 grid-column/row 决定——展开时的
   块内重排需要显式坐标，不能交给 CSS 的 dense 去猜。这里只留一条兜底跨度。 */
html[data-theme] #homeRecommended .pod-card { grid-column: span 3; grid-row: span 2; }


html[data-theme] .pod-grid { gap: 2px; }

html[data-theme] .pod-card {
  position: relative;
  display: block;
  overflow: hidden;
  padding: 0;
  border: 0;
  border-radius: 0;
  aspect-ratio: auto;
  height: 100%;
  min-height: 0;
  background: var(--coverbg);
  color: var(--ink);
  counter-increment: folia-poster;
  box-shadow: none;
  isolation: isolate;
  transition: filter var(--motion-slow) var(--ease), box-shadow var(--motion-slow) var(--ease);
}

html[data-theme] .pod-card-main {
  position: absolute;
  inset: 0;
  z-index: auto;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 5px;
  padding: 24px;
  color: inherit;
  text-decoration: none;
}

html[data-theme] .pod-card .pod-art {
  position: absolute;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
  aspect-ratio: auto;
  border: 0;
  border-radius: 0;
  background: var(--coverbg);
  outline: 0;
}
html[data-theme] .pod-card .pod-art img { width: 100%; height: 100%; object-fit: cover; }
html[data-theme] .pod-card .pod-art span {
  font-size: 34px;
  font-weight: 800;
  letter-spacing: -0.04em;
  color: rgba(255, 255, 255, 0.8);
}

/* 压字黑幕：Folia 的 5% / 24% / 92% 三段 */
html[data-theme] .pod-card::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background: linear-gradient(180deg,
    rgba(0, 0, 0, 0.05) 34%,
    rgba(0, 0, 0, 0.24) 56%,
    rgba(0, 0, 0, 0.92) 100%);
}
/* 展开态照 Folia 的 `.lattice-poster.is-expanded .lattice-poster-shade`：
   在整块瓦片上再压一层"底 + 左"的复合黑幕，字幕落在左下这块暗区里。
   字本身不再垫任何底板——可读性是卡片级的渐变压暗，不是一块贴纸。 */
html[data-theme] #homeRecommended .pod-card.is-peek::after,
html[data-theme] #homeRecommended .pod-card.is-playing-tile::after {
  background:
    linear-gradient(0deg,
      rgba(0, 0, 0, 0.88) 0%,
      rgba(0, 0, 0, 0.66) 18%,
      rgba(0, 0, 0, 0.34) 42%,
      rgba(0, 0, 0, 0.12) 58%,
      rgba(0, 0, 0, 0) 70%),
    linear-gradient(90deg,
      rgba(0, 0, 0, 0.88) 0%,
      rgba(0, 0, 0, 0.50) 52%,
      rgba(0, 0, 0, 0.08) 100%);
}

html[data-theme] .pod-card .pod-card-main > strong {
  position: relative;
  z-index: 2;
  margin-block: -0.14em;
  padding-block: 0.14em;
  font-size: clamp(26px, 2.6vw, 46px);
  line-height: 0.96;
  font-weight: 800;
  letter-spacing: -0.045em;
  color: var(--ink);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-wrap: balance;
}

html[data-theme] .pod-card .pod-meta {
  position: relative;
  z-index: 2;
  font-size: 13px;
  font-weight: 650;
  letter-spacing: 0.01em;
  color: rgba(247, 244, 238, 0.78);
  white-space: nowrap;
  text-overflow: ellipsis;
  overflow: hidden;
}

html[data-theme] .pod-card .pod-name {
  position: relative;
  z-index: 2;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--accent);
}
html[data-theme] .pod-card .pod-latest,
html[data-theme] .pod-card .pod-badges,
html[data-theme] .pod-card .pod-actions { display: none !important; }
html[data-theme] .pod-card .pod-desc { display: none !important; }

/* 角标编号 */
html[data-theme] .pod-card::before {
  content: counter(folia-poster, decimal-leading-zero);
  position: absolute;
  z-index: 3;
  top: 14px;
  left: 14px;
  padding: 5px 8px;
  border: 0;
  border-radius: 0;
  background: rgba(0, 0, 0, 0.62);
  color: rgba(255, 255, 255, 0.92);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  font-variant-numeric: tabular-nums;
}

html[data-theme] #homeRecommended .pod-card:hover { filter: saturate(1.08) brightness(1.05); z-index: 3; }
html[data-theme] .pod-card:hover { filter: saturate(1.08) brightness(1.05); z-index: 3; }
/* 按下 / 悬停的微动效：Folia 的封面是会呼吸的，不是死图 */
html[data-theme] #homeRecommended .pod-card { transition: filter var(--motion-slow) var(--ease), box-shadow var(--motion-slow) var(--ease), scale var(--motion-fast) var(--ease); }
html[data-theme] #homeRecommended .pod-card:active { scale: 0.985; }
html[data-theme] #homeRecommended .pod-card .pod-art img {
  transform: scale(1.001);
  transition: transform 0.7s var(--ease);
}
html[data-theme] #homeRecommended .pod-card:hover .pod-art img { transform: scale(1.035); }
html[data-theme] #homeRecommended .pod-card .pod-card-main > strong { transition: font-size var(--motion-slow) var(--ease), color var(--motion-slow) var(--ease); }

/* Folia 的“正在播放”：瓦片里压一圈珊瑚描边 + 角标点亮 + 右下小胶囊 */
html[data-theme] .pod-card.is-playing-tile {
  z-index: 2;
  box-shadow: inset 0 0 0 2px var(--accent);
}
html[data-theme] .pod-card.is-playing-tile::before {
  background: var(--accent);
  color: #0a0a0a;
}
html[data-theme] .pod-card.is-playing-tile .pod-card-main::after {
  content: "● 正在播放";
  position: absolute;
  z-index: 3;
  right: 12px;
  bottom: 12px;
  padding: 5px 9px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.62);
  color: var(--accent);
  font: 700 11px/1 var(--sans);
  letter-spacing: 0.06em;
}
html[data-theme] .pod-card.is-playing-tile-live .pod-card-main::after { color: #fff; }
html[data-theme] .pod-card.is-playing-tile-live::before { animation: foliaBadgePulse 1.6s var(--ease) infinite; }
@keyframes foliaBadgePulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.62; }
}

/* 每格字号按格子大小定，小方格不顶字（尺寸来自 Folia 12×8 格子）。
   Folia 的 201px 小瓦片标题约 23.6px，这里不再压到 14–19px。 */
html[data-theme] #homeRecommended .pod-card .pod-card-main { padding: 14px 14px 15px; }
html[data-theme] #homeRecommended .pod-card .pod-card-main > strong { font-size: clamp(26px, 2.6vw, 46px); -webkit-line-clamp: 2; }
html[data-theme] #homeRecommended .pod-card .pod-meta { font-size: 11.5px; }

/* 字号只看这一席实际占几格（data-tile 由 JS 按模板块写），不再跟 nth-child 周期。 */

html[data-theme] #page-home #homeRecommended .pod-card[data-tile="big"] .pod-card-main > strong {
  font-size: clamp(24px, 2.4vw, 44px);
  -webkit-line-clamp: 3;
}
html[data-theme] #page-home #homeRecommended .pod-card[data-tile="small"] .pod-card-main {
  padding: 10px 10px 11px;
}
html[data-theme] #page-home #homeRecommended .pod-card[data-tile="small"] .pod-card-main > strong {
  font-size: clamp(21px, 1.7vw, 24px);
  -webkit-line-clamp: 2;
}
html[data-theme] #page-home #homeRecommended .pod-card[data-tile="small"] .pod-meta { font-size: 11px; }
/* Folia 的悬浮快钮：指针停在瓦片上，右上角浮出 40px 玻璃圆钮 */
html[data-theme] #homeRecommended .pod-card .pod-actions {
  display: flex !important;
  position: absolute;
  z-index: 4;
  top: 14px;
  right: 14px;
  gap: 6px;
  opacity: 0;
  pointer-events: none;
  transform: translateY(-4px);
  transition: opacity var(--motion-normal) var(--ease), transform var(--motion-normal) var(--ease);
}
html[data-theme] #homeRecommended .pod-card:hover .pod-actions,
html[data-theme] #homeRecommended .pod-card:focus-within .pod-actions {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}
html[data-theme] #homeRecommended .pod-card .pod-actions .btn {
  position: relative;
  width: 36px;
  height: 36px;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.72);
  /* 原来是 blur(8px)：一屏 168 块瓦片 × 每块一颗毛玻璃，GPU 里就多出 168 个
     backdrop 层（实测 GPU 进程 449MB 的大头）。底本来就只有 62% 黑，改成实底
     0.72 在亮封面上更好读，观感几乎无差。 */
  color: #fff;
  font-size: 0;
  line-height: 0;
  letter-spacing: 0;
  box-shadow: none;
  transition: background-color var(--motion-normal) var(--ease), border-color var(--motion-normal) var(--ease), scale var(--motion-fast) var(--ease);
}
html[data-theme] #homeRecommended .pod-card .pod-actions .btn:hover { background: var(--accent); border-color: var(--accent); }
html[data-theme] #homeRecommended .pod-card .pod-actions .btn:active { scale: 0.92; }
html[data-theme] #homeRecommended .pod-card .pod-actions .btn::after {
  content: "＋";
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font: 700 16px/1 var(--sans);
  letter-spacing: 0;
  transform: translateY(-0.5px);   /* 全角＋的基线偏下，光学上提半像素 */
}
/* 墙上每张卡都是已订阅：快钮不该再显示“＋”（那是“加入”的意思）。
   内置节目给对勾（管理中），站外节目给箭头（进入节目页）。 */
html[data-theme] #homeRecommended .pod-card .pod-actions .btn[data-quick="manage"]::after {
  content: "✓";
  font-size: 14px;
  transform: translateY(-1px);
}
html[data-theme] #homeRecommended .pod-card .pod-actions .btn[data-quick="open"]::after {
  content: "↗";
  font-size: 14px;
  transform: none;
}

/* 展开态：瓦片原地长成 6×4（Folia 点一下就是把这块瓦片撑开），标题与元信息一起放大 */
html[data-theme] #page-home #homeRecommended .pod-card.is-peek,
html[data-theme] #page-home #homeRecommended .pod-card.is-playing-tile {
  grid-column: span 6;
  grid-row: span 6;      /* 比墙上任何一个槽位都高：6×4 的大块点开也一定看得出放大 */
  z-index: 6;
  box-shadow: inset 0 0 0 2px rgba(247, 244, 238, 0.22);
}
html[data-theme] #page-home #homeRecommended .pod-card.is-playing-tile {
  box-shadow: inset 0 0 0 2px var(--accent);
}
html[data-theme] #page-home #homeRecommended .pod-card.is-peek .pod-card-main,
html[data-theme] #page-home #homeRecommended .pod-card.is-playing-tile .pod-card-main {
  padding: 26px 26px 64px;
  gap: 8px;
}
html[data-theme] #page-home #homeRecommended .pod-card.is-peek .pod-card-main > strong,
html[data-theme] #page-home #homeRecommended .pod-card.is-playing-tile .pod-card-main > strong {
  font-size: clamp(30px, 3vw, 52px);
  -webkit-line-clamp: 3;
}
html[data-theme] #page-home #homeRecommended .pod-card.is-peek .pod-meta,
html[data-theme] #page-home #homeRecommended .pod-card.is-playing-tile .pod-meta { font-size: 14px; }
/* 尺寸补间时把这张卡的内部布局/样式隔离开：每帧只重排它自己，不牵动 168 张卡 */
html[data-theme] #homeRecommended .pod-card.is-peek {
  contain: layout style;
  will-change: width, height;
}

/* 展开后的底部动作条：进入节目页 / 收起 */
html[data-theme] #homeRecommended .tile-peek {
  position: absolute;
  z-index: 5;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 22px 20px;
  opacity: 0;
  transform: translateY(6px);
  pointer-events: none;
  transition: opacity var(--motion-normal) var(--ease), transform var(--motion-normal) var(--ease);
}
html[data-theme] #homeRecommended .pod-card.is-peek .tile-peek { opacity: 1; transform: none; pointer-events: auto; }
html[data-theme] #homeRecommended .tile-peek-kicker {
  margin-right: auto;
  font: 700 11px/1 var(--sans);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(247, 244, 238, 0.6);
}
html[data-theme] #homeRecommended .tile-peek-actions { display: flex; gap: 6px; }
html[data-theme] #homeRecommended .tile-peek-btn {
  appearance: none;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 999px;
  padding: 9px 14px;
  /* 这四颗按钮挂在会改尺寸的瓦片上：backdrop-filter 每帧都要重算底图，实测把 180Hz 打成 100fps。用实底替代。 */
  background: rgba(8, 8, 10, 0.78);
  color: var(--ink);
  font: 700 12px/1 var(--sans);
  text-decoration: none;
  cursor: pointer;
  transition: background-color var(--motion-normal) var(--ease), border-color var(--motion-normal) var(--ease),
    color var(--motion-normal) var(--ease), transform var(--motion-normal) var(--ease), scale var(--motion-fast) var(--ease);
}
html[data-theme] #homeRecommended .tile-peek-btn:hover { transform: translateY(-1px); background: rgba(255, 255, 255, 0.14); }
html[data-theme] #homeRecommended .tile-peek-btn:active { scale: 0.96; }
html[data-theme] #homeRecommended .tile-peek-btn.primary:hover { background: #ff7a64; border-color: #ff7a64; }
html[data-theme] #homeRecommended .tile-peek-btn.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #0a0a0a;
}

/* 正在播放的瓦片压当前句（Folia 播放态瓦片就是一块“正在发生的歌词板”） */
html[data-theme] #homeRecommended .tile-live-lyric {
  position: absolute;
  z-index: 4;
  left: 24px;
  right: 24px;
  bottom: 42px;
  display: none;
  font: 650 clamp(15px, 1.4vw, 20px)/1.28 var(--sans);
  color: rgba(255, 255, 255, 0.92);
  text-wrap: balance;
  /* 不再裁切：字号由脚本压到放得下为止，真到极限宁可越出这条框也不吃字 */
  overflow: visible;
  pointer-events: none;
  /* 固定字号之后超长的一句靠整块上移留住正在读的那行（Folia 的 long-line offset） */
  transform: translateY(calc(-1 * var(--tl-shift, 0px)));
}
html[data-theme] #homeRecommended .pod-card.is-playing-tile .tile-live-lyric {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 0.55em;
  /* 字幕块贴住 30% 那条底线，高度由内容决定、只往上长：
     三行都完整显示，不再被固定的上下边界压扁。 */
  top: auto;
  bottom: 30%;
  max-height: 66%;
  font-family: var(--sans);
  font-weight: 650;
  /* 字号由脚本按可用高度逐档下调（fitLyricBox），这里只给一个上限兜底 */
  font-size: var(--tl-fs, clamp(18px, 1.7vw, 26px));
  line-height: 1.3;
  /* 没有底板之后，可读性只靠描边：四向 1px 暗影把字形边缘压出来，
     再补一层 10px 柔影托住整句——不是色块，完全跟着字走。 */
  text-shadow: var(--tl-shadow, 0 0 1px rgba(0, 0, 0, 0.92), 1px 1px 0 rgba(0, 0, 0, 0.88),
    -1px 1px 0 rgba(0, 0, 0, 0.88), 1px -1px 0 rgba(0, 0, 0, 0.88), -1px -1px 0 rgba(0, 0, 0, 0.88),
    0 2px 10px rgba(0, 0, 0, 0.45));
}
/* 三行字幕同字号：只靠明暗和字重分主次，不再把上一句/下一句缩成小字。
   一行里放不下就换行——以前这里锁两行 clamp，flex 一压就变成
   “一行 + 省略号”，句子里后半截直接丢掉。 */
html[data-theme] #homeRecommended .tile-live-lyric .tl-line {
  display: block;
  flex: 0 0 auto;
  position: relative;
  z-index: 1;
  min-height: 0;
  white-space: normal;
  overflow-wrap: break-word;
  overflow: visible;
  transition: opacity var(--motion-slow) var(--ease);
}
/* 字幕不再垫底板：以前亮封面会抬 --tl-plate（0~0.58）在字后面铺一层柔和暗幕，
   视觉上像贴了一块半透明色块。现在只用文字自身的描边阴影，任何封面都是"字压在图
   上"，不再出现整块背景。可读性靠下面这几层紧贴的暗影 + 词高亮解决。 */
html[data-theme] #homeRecommended .tile-live-lyric .tl-prev,
html[data-theme] #homeRecommended .tile-live-lyric .tl-next {
  font-size: 1em;
  font-weight: 600;
  color: var(--tl-fg-dim, rgba(255, 255, 255, 0.55));
}
html[data-theme] #homeRecommended .tile-live-lyric .tl-cur {
  font-weight: 700;
  color: var(--tl-fg, rgba(255, 255, 255, 0.96));
}
/* 播放态的封面保持放大（不随上一条的 hover 收镜） */
html[data-theme] #homeRecommended .pod-card.is-playing-tile .pod-art img {
  transform: scale(1.07);
}
/* 播放态瓦片的版面是“封面 + 大字标题 + 当前句”：标题往上收，歌词独占底部一条。
   没有字幕的集子不该留那 112px 空档——`has-tile-lyric` 由脚本按“真有句子要显示”来挂。 */
html[data-theme] #page-home #homeRecommended .pod-card.is-playing-tile .pod-card-main { padding: 26px 26px 34px; }
html[data-theme] #page-home #homeRecommended .pod-card.is-playing-tile.has-tile-lyric .pod-card-main { padding-bottom: 112px; }
html[data-theme] #page-home #homeRecommended .pod-card.is-playing-tile .pod-card-main > strong {
  font-size: clamp(22px, 2.2vw, 36px);
  -webkit-line-clamp: 2;
}
html[data-theme] #page-home #homeRecommended .pod-card.is-playing-tile .pod-meta { display: none; }
html[data-theme] #homeRecommended .pod-card.is-playing-tile .pod-card-main::after { bottom: 16px; right: 16px; }

html[data-theme] .pod-card:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}
/* 方向键选中的瓦片：和鼠标悬停分开，键盘在墙上走位时始终有一个明确的落点。 */
html[data-theme] #homeRecommended .pod-card.is-cursor {
  z-index: 4;
  outline: 2px solid var(--accent);
  outline-offset: -3px;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.25);
}
html[data-theme] #homeRecommended .pod-card.is-cursor .pod-card-main > strong { color: var(--bright); }

/* ---------- 5. 播放条：悬浮胶囊 ---------- */
/* ---------- 5. 播放条：默认缩成小胶囊，悬停或播放页才展开 ---------- */
/* 基础层 `body:not(.player-open) .dock{display:none!important}` 会把底栏从墙页拿走；
   Folia 的墙上是常驻迷你播放条，这里把它请回来（播放页照旧展开） */
html[data-theme] body:not(.player-open) .dock { display: block !important; }
/* 播放页（含精听/字幕页）基础层会把底栏拉成通栏并清掉 translate，只剩 left:50% → 整条右移半个身位被切掉。
   这里把播放页也钉回“居中胶囊”，translate 显式写上，不再依赖基础层的居中。 */
html[data-theme] body.player-open .dock {
  left: 50%;
  right: auto;
  bottom: 18px;
  width: min(760px, calc(100vw - 48px));
  max-width: none;
  border: 1px solid var(--folia-glass-line);
  border-radius: 26px;
  translate: -50% 0;
}
html[data-theme] .dock {
  position: fixed;
  left: 50%;
  bottom: 18px;
  translate: -50% 0;
  width: min(760px, calc(100vw - 140px));
  padding: 10px 16px 12px;
  border: 1px solid var(--folia-glass-line);
  border-radius: 24px;
  /* 和搜索胶囊、侧栏同一层烟熏玻璃；展开只动宽度，模糊层跟着几何自适应。 */
  background: var(--folia-glass);
  backdrop-filter: var(--folia-glass-blur);
  -webkit-backdrop-filter: var(--folia-glass-blur);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.60), 0 0 0 1px rgba(253, 92, 71, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.09);
  overflow: hidden;
  will-change: width;
  transition: width var(--motion-slow) cubic-bezier(0.2, 0.9, 0.2, 1),
    translate var(--motion-normal) var(--ease),
    box-shadow var(--motion-normal) var(--ease);
}
/* 缩小态：只有封面、标题和播放键，宽 260px 的圆角胶囊 */
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) {
  width: 260px;
  padding: 7px 9px 7px 7px;
  border-radius: 26px;
  background: var(--folia-glass);
  box-shadow: 0 18px 46px rgba(0, 0, 0, 0.54), 0 0 0 1px rgba(253, 92, 71, 0.10), inset 0 1px 0 rgba(255, 255, 255, 0.07);
}
html[data-theme] body:not(.player-open) .dock:hover,
html[data-theme] body:not(.player-open) .dock:focus-within {
  translate: -50% -2px;
  box-shadow: 0 34px 88px rgba(0, 0, 0, 0.68), 0 0 0 1px rgba(253, 92, 71, 0.14), inset 0 1px 0 rgba(255, 255, 255, 0.10);
}
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .pbar,
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .deck-lab,
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .epstep,
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .skipbtn,
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .dockquick,
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .docktools,
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .pmeta {
  display: none;
}
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .dockrow {
  gap: 8px;
}
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .nowplay {
  flex: 1;
  min-width: 0;
}
html[data-theme] body:not(.player-open) .dock:not(:hover):not(:focus-within) .ptitle {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
html[data-theme] .dock .pbar { height: 3px; margin: 0 0 9px; background: rgba(255, 255, 255, 0.10); border-radius: 999px; }
html[data-theme] .dock .pbar .track { border-radius: 999px; overflow: hidden; }
html[data-theme] .dock .pfill {
  height: 3px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--accent), color-mix(in srgb, var(--accent) 55%, #fff));
}
html[data-theme] .dock .seek { opacity: 0; }
html[data-theme] .dockrow { gap: 10px; }
html[data-theme] .dock .cover {
  border-radius: 12px;
  width: 42px;
  height: 42px;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.16), 0 8px 22px rgba(0, 0, 0, 0.5);
}
html[data-theme] .dock .ptext strong { font: 700 13.5px/1.3 var(--sans); color: var(--ink); letter-spacing: -0.01em; }
html[data-theme] .dock .ptext span { font: 500 11px/1.4 var(--sans); color: var(--muted); }
/* 底栏主按钮沿用主题的珊瑚渐变，只收小一圈，别在缩起时压过标题 */
html[data-theme] .dock .playbtn {
  width: 44px;
  height: 44px;
  font-size: 15px;
  box-shadow: 0 12px 26px -10px color-mix(in srgb, var(--accent) 65%, transparent), inset 0 1px 0 rgba(255, 255, 255, 0.45);
}
html[data-theme] .dock .playbtn .ico { width: 16px; height: 16px; }
html[data-theme] .dock .play,
html[data-theme] .dock .round-play {
  width: 44px;
  height: 44px;
  border: 0;
  border-radius: 999px;
  background: #fff;
  color: #0a0a0a;
  font-size: 15px;
  box-shadow: 0 10px 26px rgba(0, 0, 0, 0.45);
}
html[data-theme] .dockicon {
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.07);
  color: var(--ink);
}
html[data-theme] .dockicon.on { background: color-mix(in srgb, var(--accent) 24%, transparent); color: #fff; }
html[data-theme] .dockquickbtn { border: 0; border-radius: 999px; background: rgba(255, 255, 255, 0.07); color: var(--ink); }
html[data-theme] .dock .tnum,
html[data-theme] .dock .ptime { font-variant-numeric: tabular-nums; color: var(--muted); font-size: 11.5px; }

/* 墙页右下角的「回到正在播放」浮钮（Folia 的定位当前播放） */
html[data-theme="ct-pack-folia-poster"] .folia-locate {
  position: fixed;
  right: 24px;
  bottom: 104px;
  z-index: 30;
  display: flex;
  align-items: center;
  gap: 9px;
  height: 42px;
  padding: 0 16px 0 12px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 999px;
  background: rgba(10, 10, 12, 0.88);
  color: #f7f4ee;
  font: 700 12px/1 var(--sans);
  letter-spacing: 0.02em;
  box-shadow: 0 16px 38px rgba(0, 0, 0, 0.52);
  opacity: 0;
  pointer-events: none;
  transform: translateY(8px);
  transition: opacity var(--motion-slow) var(--ease), transform var(--motion-slow) var(--ease),
    background-color var(--motion-fast) var(--ease), border-color var(--motion-fast) var(--ease);
}
html[data-theme="ct-pack-folia-poster"] .folia-locate.on { opacity: 1; pointer-events: auto; transform: none; }
html[data-theme="ct-pack-folia-poster"] .folia-locate:hover { background: var(--accent); border-color: var(--accent); }
html[data-theme="ct-pack-folia-poster"] .folia-locate-bars { display: flex; align-items: flex-end; gap: 2px; height: 14px; }
html[data-theme="ct-pack-folia-poster"] .folia-locate-bars i { width: 2px; border-radius: 1px; background: currentColor; animation: foliaLocateBars 0.9s var(--ease) infinite alternate; }
html[data-theme="ct-pack-folia-poster"] .folia-locate-bars i:nth-child(1) { height: 7px; animation-delay: 0s; }
html[data-theme="ct-pack-folia-poster"] .folia-locate-bars i:nth-child(2) { height: 13px; animation-delay: var(--motion-slow); }
html[data-theme="ct-pack-folia-poster"] .folia-locate-bars i:nth-child(3) { height: 9px; animation-delay: 0.42s; }
@keyframes foliaLocateBars {
  from { transform: scaleY(0.55); opacity: 0.55; }
  to   { transform: scaleY(1); opacity: 1; }
}
html[data-theme="ct-pack-folia-poster"] #homeRecommended .pod-card.locate-flash { animation: foliaLocateFlash 0.9s var(--ease); }
@keyframes foliaLocateFlash {
  0%   { box-shadow: inset 0 0 0 2px var(--accent); }
  55%  { box-shadow: inset 0 0 0 6px color-mix(in srgb, var(--accent) 55%, transparent); }
  100% { box-shadow: inset 0 0 0 2px var(--accent); }
}

/* ---------- 6. 播放页 / 阅读页：一块黑玻璃 ---------- */
html[data-theme] .reader { background: #08080a; }
html[data-theme] .reader-top-actions {
  height: 56px;
  padding: 0 14px;
  border-bottom: 1px solid var(--line2);
  background: rgba(8, 8, 10, 0.7);
  backdrop-filter: blur(18px);
}
html[data-theme] .reader-top-actions .reader-back,
html[data-theme] .reader-top-actions .reader-rail-btn {
  height: 30px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  font: 600 11.5px/1 var(--sans);
  letter-spacing: 0.02em;
}
html[data-theme] .reader-top-actions .reader-back:hover,
html[data-theme] .reader-top-actions .reader-rail-btn:hover { border-color: rgba(255, 255, 255, 0.26); background: rgba(255, 255, 255, 0.06); }
html[data-theme] .reader-show-pill {
  border: 0;
  background: transparent;
  color: rgba(247, 244, 238, 0.55);
  font: 800 11px/1 var(--mono);
  letter-spacing: 0.22em;
}
html[data-theme] .reader-rail {
  background: #0a0a0c;
  border-color: var(--line2);
}
html[data-theme] .rail-kicker { font: 800 11px/1 var(--sans); letter-spacing: 0.26em; color: var(--dim); }
html[data-theme] .reader-rail h2 { font: 800 15px/1.25 var(--sans); letter-spacing: -0.02em; color: var(--ink); }

/* 正文：Folia 的歌词墙 */
html[data-theme] #transcript,
html[data-theme] .tx-list { background: transparent; }
html[data-theme] .cue {
  border: 0;
  border-bottom: 1px solid var(--line2);
  border-radius: 0;
  background: transparent;
}
html[data-theme] .cue:hover { background: rgba(255, 255, 255, 0.035); }
html[data-theme] .cue.active,
html[data-theme] .cue.is-active {
  background: linear-gradient(90deg, rgba(253, 92, 71, 0.13), rgba(253, 92, 71, 0) 62%);
  box-shadow: inset 2px 0 0 var(--accent);
}
html[data-theme] .cue .cue-text { font: 500 16px/1.65 var(--sans); color: rgba(247, 244, 238, 0.72); letter-spacing: -0.005em; }
html[data-theme] .cue.active .cue-text { color: var(--ink); }
html[data-theme] .cue .cue-text b,
html[data-theme] .cue .cue-text mark,
html[data-theme] .word.on {
  color: #fff;
  background: none;
  text-shadow: 0 0 18px rgba(253, 92, 71, 0.55);
}
html[data-theme] .cue .cue-time { font: 500 11px/1 var(--mono); letter-spacing: 0.04em; color: var(--dim); }

/* ---------- 7. 其余页面：同一套扁平语言，不带卡片 ---------- */
/* 统一给页面左右留白，左上角悬浮钮不再压住标题 */
html[data-theme] .page { padding: 26px 3.2vw 44px 78px; }
html[data-theme] .page-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; padding: 6px 0 18px; border: 0; }
html[data-theme] .page-head h1,
html[data-theme] #page-settings h1 {
  font: 800 clamp(34px, 4.2vw, 60px)/0.98 var(--sans);
  letter-spacing: -0.05em;
  color: var(--ink);
}
html[data-theme] .page-head .eyebrow,
html[data-theme] #page-settings .eyebrow { font: 800 11px/1 var(--sans); letter-spacing: 0.26em; color: var(--accent); }

html[data-theme] .settings-menu,
html[data-theme] .set-nav { background: rgba(255, 255, 255, 0.04); border: 1px solid var(--line2); border-radius: 14px; }
html[data-theme] .settings-menu button.active { background: rgba(255, 255, 255, 0.08); color: var(--ink); box-shadow: inset 2px 0 0 var(--accent); border-radius: 8px; }
html[data-theme] .setting-row { border-bottom: 1px solid var(--line2); }
html[data-theme] .toggle,
html[data-theme] .switch { border-radius: 999px; }
html[data-theme] .toggle.on,
html[data-theme] .switch.on { background: var(--accent); }

html[data-theme] .ct-grid,
html[data-theme] .theme-grid { gap: 10px; }
html[data-theme] .ct-card,
html[data-theme] .theme-card { border-radius: 12px; border-color: var(--line); }
html[data-theme] .ct-card.on,
html[data-theme] .theme-card.on { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent); }

/* ---------- 7. 节目页：封面铺顶 + 压字大标题 + 发丝单集 ---------- */
html[data-theme] #page-podcast { position: relative; padding: 0; }

/* 标题压在封面下沿，和 Folia 的海报页同一套排法 */
html[data-theme] #page-podcast .page-head {
  position: absolute;
  left: 0;
  right: 0;
  top: calc(54vh - 150px);
  z-index: 3;
  display: block;
  margin: 0;
  padding: 0 3.2vw;
  pointer-events: none;
  background: none;
  border: 0;
}
html[data-theme] #page-podcast .page-head .eyebrow { margin-bottom: 10px; }
html[data-theme] #page-podcast .page-head h1 { text-shadow: 0 8px 40px rgba(0, 0, 0, 0.55); }
html[data-theme] #page-podcast .page-head .subtitle {
  margin-top: 8px;
  font: 650 13px/1.4 var(--sans);
  letter-spacing: 0.02em;
  color: rgba(247, 244, 238, 0.72);
}
html[data-theme] #page-podcast .page-head .btn {
  position: fixed;
  top: 62px;
  right: 18px;
  pointer-events: auto;
  height: 36px;
  padding: 0 14px;
  border: 0;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.46);
  backdrop-filter: blur(12px);
  color: var(--ink);
  border: 1px solid rgba(255, 255, 255, 0.14);
  font-size: 12px;
}

/* 封面当背景铺满上半屏 */
html[data-theme] #page-podcast .show-hero {
  position: relative;
  display: block;
  height: 54vh;
  margin: 0 -0vw 26px;
  padding: 0;
  overflow: hidden;
  border: 0;
  border-radius: 0;
  background: #0a0a0b;
}
html[data-theme] #page-podcast .show-hero .pod-art {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
  border-radius: 0;
  filter: saturate(1.02);
}
html[data-theme] #page-podcast .show-hero .pod-art img { width: 100%; height: 100%; object-fit: cover; }
html[data-theme] #page-podcast .show-hero::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(0, 0, 0, 0.34) 0%, rgba(0, 0, 0, 0.10) 28%, rgba(0, 0, 0, 0.62) 56%, rgba(0, 0, 0, 0.88) 80%, var(--bg) 100%);
}
html[data-theme] #page-podcast .show-hero > div {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 10px;
  height: 100%;
  padding: 26px 3.2vw 20px;
  background: linear-gradient(0deg, rgba(0, 0, 0, 0.92) 0%, rgba(0, 0, 0, 0.55) 42%, rgba(0, 0, 0, 0.16) 72%, rgba(0, 0, 0, 0.05) 100%);
}

/* 简介收成两行小字，动作做成玻璃胶囊 */
html[data-theme] #page-podcast .show-hero .detail-meta,
html[data-theme] #page-podcast .show-hero .show-desc-wrap { display: none; }
html[data-theme] #page-podcast .detail-meta { gap: 14px; font: 700 11px/1 var(--sans); letter-spacing: 0.16em; text-transform: uppercase; color: rgba(247, 244, 238, 0.6); }
html[data-theme] #page-podcast .show-desc { max-width: 720px; font: 500 13px/1.6 var(--sans); color: rgba(247, 244, 238, 0.68); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
html[data-theme] #page-podcast .show-desc-toggle { display: none; }
html[data-theme] #page-podcast .detail-actions .btn {
  height: 38px;
  padding: 0 18px;
  border: 0;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(10px);
  color: var(--ink);
  font: 650 13px/1 var(--sans);
}
html[data-theme] #page-podcast .detail-actions .btn.primary { background: var(--accent); color: #170b08; }

/* 单集：整宽发丝行，去掉卡片和圆角 */
html[data-theme] #page-podcast .grid.two { display: block; margin: 0; padding: 0 3.2vw 40px; gap: 0; }
html[data-theme] #page-podcast .card,
html[data-theme] #page-podcast .card-pad {
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
html[data-theme] #page-podcast .card-pad + .card-pad { margin-top: 34px; }
html[data-theme] #page-podcast .card-pad > .section-title {
  padding-bottom: 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.10);
  font: 800 11px/1 var(--sans);
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: rgba(247, 244, 238, 0.62);
}
html[data-theme] #page-podcast .ep-filter-row { margin: 12px 0 4px; gap: 6px; }
html[data-theme] #page-podcast .ep-filter-row button { height: 28px; padding: 0 12px; border: 0; border-radius: 999px; background: rgba(255, 255, 255, 0.06); font-size: 12px; color: rgba(247, 244, 238, 0.66); }
html[data-theme] #page-podcast .ep-filter-row button.on { background: var(--accent); color: #fff; }
html[data-theme] #page-podcast .ep-row,
html[data-theme] #page-podcast .ep-item,
html[data-theme] #page-podcast .episode-row {
  padding: 16px 4px;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0;
  background: transparent;
}
html[data-theme] #page-podcast .kv { padding: 12px 4px; border-bottom: 1px solid rgba(255, 255, 255, 0.08); background: transparent; }
html[data-theme] #page-podcast .setting-row { padding: 14px 4px; border-bottom: 1px solid rgba(255, 255, 255, 0.08); background: transparent; }

/* ---------- 8. 动效：节目 ↔ 单集 的层级递进（照 Folia 的"瓦片就地展开"节奏） ---------- */
/* 1) 页面进出：只淡入 + 轻移，避免影响内部 fixed 元素 */
html[data-theme] .page.active { animation: foliaPageIn 0.34s var(--ease) both; }
@keyframes foliaPageIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* 2) 进节目页：封面像被瓦片展开一样裁开，同时缓慢收镜 */
html[data-theme] #page-podcast .show-hero {
  animation: foliaHeroOpen 0.66s cubic-bezier(0.16, 0.84, 0.24, 1) both;
}
@keyframes foliaHeroOpen {
  from { clip-path: inset(14% 24% 24% 24% round 12px); }
  to   { clip-path: inset(0 0 0 0 round 0); }
}
html[data-theme] #page-podcast .show-hero .pod-art {
  animation: foliaCoverZoom 0.85s cubic-bezier(0.2, 0.9, 0.2, 1) both;
}
@keyframes foliaCoverZoom {
  from { transform: scale(1.14); }
  to   { transform: scale(1); }
}

/* 3) 标题三件套依次上浮（eyebrow → 大标题 → 副行 → 按钮） */
html[data-theme] #page-podcast .page-head > div > .eyebrow { animation: foliaRise 0.5s 0.10s var(--ease) both; }
html[data-theme] #page-podcast .page-head h1 { animation: foliaRise 0.5s var(--motion-normal) var(--ease) both; }
html[data-theme] #page-podcast .page-head .subtitle { animation: foliaRise 0.5s var(--motion-slow) var(--ease) both; }
html[data-theme] #page-podcast .detail-actions { animation: foliaRise 0.5s 0.34s var(--ease) both; }
@keyframes foliaRise {
  from { opacity: 0; transform: translateY(14px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* 4) 单集行阶梯出现：节目（父）先到，单集（子）随后一条条落位 */
html[data-theme] #page-podcast .ep-row { animation: foliaRowIn 0.42s var(--ease) both; }
html[data-theme] #page-podcast .ep-row:nth-child(5n + 1) { animation-delay: 0.36s; }
html[data-theme] #page-podcast .ep-row:nth-child(5n + 2) { animation-delay: 0.40s; }
html[data-theme] #page-podcast .ep-row:nth-child(5n + 3) { animation-delay: 0.44s; }
html[data-theme] #page-podcast .ep-row:nth-child(5n + 4) { animation-delay: 0.48s; }
html[data-theme] #page-podcast .ep-row:nth-child(5n + 5) { animation-delay: 0.52s; }
@keyframes foliaRowIn {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* 5) 首页四张瓦片铺开：从略缩到满格，按顺序错开 */
html[data-theme] #homeRecommended .pod-card { animation: foliaTileIn 0.56s var(--ease) both; }
html[data-theme] #homeRecommended .pod-card:nth-child(1) { animation-delay: 0.02s; }
html[data-theme] #homeRecommended .pod-card:nth-child(2) { animation-delay: 0.08s; }
html[data-theme] #homeRecommended .pod-card:nth-child(3) { animation-delay: var(--motion-fast); }
html[data-theme] #homeRecommended .pod-card:nth-child(4) { animation-delay: 0.20s; }
@keyframes foliaTileIn {
  from { opacity: 0; transform: scale(0.985); }
  to   { opacity: 1; transform: scale(1); }
}

/* 6) 点单集进阅读页：正文一层层浮起，衔接节目页的阶梯感 */
html[data-theme] .reader { animation: foliaPageIn var(--motion-slow) var(--ease) both; }
html[data-theme] #transcript .cue:nth-child(-n + 8) { animation: foliaRowIn 0.4s var(--ease) both; }
html[data-theme] #transcript .cue:nth-child(1) { animation-delay: 0.06s; }
html[data-theme] #transcript .cue:nth-child(2) { animation-delay: 0.10s; }
html[data-theme] #transcript .cue:nth-child(3) { animation-delay: var(--motion-fast); }
html[data-theme] #transcript .cue:nth-child(4) { animation-delay: var(--motion-normal); }
html[data-theme] #transcript .cue:nth-child(5) { animation-delay: var(--motion-slow); }
html[data-theme] #transcript .cue:nth-child(6) { animation-delay: var(--motion-slow); }
html[data-theme] #transcript .cue:nth-child(7) { animation-delay: 0.30s; }
html[data-theme] #transcript .cue:nth-child(8) { animation-delay: 0.34s; }

/* 7) 正在播放：播放条从底部浮起，瓦片加一圈珊瑚描边（Folia 的"正在播放"标记）
   入场只放一次：这条选择器带 `body:not(.player-open)`，每次开关播放页都会重新命中，
   动画就会被重新挂上、从 opacity:0 重播——表现是点右下角封面后，底栏空一下再浮回来。
   所以用 <html> 的 .motion-intro（启动后 ~1.2s 由 13-theme.js 摘掉）做一次性闸门。 */
html[data-theme].motion-intro body:not(.player-open) .dock { animation: foliaDockUp 0.42s var(--ease) both; }
@keyframes foliaDockUp {
  from { opacity: 0; translate: -50% 18px; }
  to   { opacity: 1; translate: -50% 0; }
}
html[data-theme] .dock .cover { box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 60%, transparent); }
html[data-theme] .player-open .dock { box-shadow: 0 26px 70px rgba(0, 0, 0, 0.62), 0 0 0 1px color-mix(in srgb, var(--accent) 42%, transparent); }

/* 共享元素：从被点的那块瓦片原地放大成通栏封面（位置由 player-js 写成 --fe-inset） */
html[data-theme] #page-podcast .show-hero.is-fe {
  animation: foliaHeroFe 0.72s cubic-bezier(0.2, 0.9, 0.2, 1) both;
}
html[data-theme] #page-podcast .show-hero.is-fe .pod-art { animation: none; }
/* 飞行结束后清掉 is-fe 时不许再落回 foliaHeroOpen，否则会在 0.7s 处二次收镜 */
html[data-theme] #page-podcast .show-hero.is-fe-done,
html[data-theme] #page-podcast .show-hero.is-fe-done .pod-art { animation: none; }
/* Folia 的瓦片是直角（Lattice.css 对整个墙 *{border-radius:0!important}），所以飞行起点也不带圆角 */
@keyframes foliaHeroFe {
  from { clip-path: inset(var(--fe-inset, 0) round 0); }
  to   { clip-path: inset(0 0 0 0 round 0); }
}

/* 正在播放：单集行珊瑚内描边 + 标题提亮，播放中的按钮换成暂停 */
html[data-theme] #page-podcast .ep-row.is-playing {
  background: linear-gradient(90deg, color-mix(in srgb, var(--accent) 14%, transparent), transparent 46%);
  box-shadow: inset 2px 0 0 var(--accent);
}
html[data-theme] #page-podcast .ep-row.is-playing .ep-title { color: var(--ink); }
html[data-theme] #page-podcast .ep-row.is-playing-live .mini-btn[data-play-episode] { color: transparent; position: relative; }
html[data-theme] #page-podcast .ep-row.is-playing-live .mini-btn[data-play-episode]::after {
  content: "❚❚";
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: var(--accent);
  font-size: 11px;
  letter-spacing: 0.02em;
}

/* ---------- 9. 响应式 ---------- */
/* 侧栏是浮层，任何宽度都不占列。宽屏不把瓦片一起放大：Folia 的一格始终约 100px，
   窗口变宽就加列（12 → 14 → 16 → 18 → 20 → 24），这样 1180/1440/1600 的瓦片
   仍落在 200/300/400/600 这组尺寸上；变窄只减列、不缩字号。 */
@media (min-width: 1360px) {
  html[data-theme] #homeRecommended {
    grid-template-columns: repeat(14, minmax(0, 1fr));
    grid-auto-rows: calc((100cqw - 26px) / 14);
  }
}
@media (min-width: 1600px) {
  html[data-theme] #homeRecommended {
    grid-template-columns: repeat(16, minmax(0, 1fr));
    grid-auto-rows: calc((100cqw - 30px) / 16);
  }
}
@media (min-width: 1880px) {
  html[data-theme] #homeRecommended {
    grid-template-columns: repeat(18, minmax(0, 1fr));
    grid-auto-rows: calc((100cqw - 34px) / 18);
  }
}
@media (min-width: 2100px) {
  html[data-theme] #homeRecommended {
    grid-template-columns: repeat(20, minmax(0, 1fr));
    grid-auto-rows: calc((100cqw - 38px) / 20);
  }
}
@media (min-width: 2400px) {
  html[data-theme] #homeRecommended {
    grid-template-columns: repeat(24, minmax(0, 1fr));
    grid-auto-rows: calc((100cqw - 46px) / 24);
  }
}
@media (max-width: 1100px) {
  html[data-theme] .nav button { width: 32px; height: 32px; }
}
/* 二维墙里一块必须永远是 12 栏 × 8 行：上面那些“窗口变宽就加列”的断点是给单列瀑布用的，
   落进 .folia-wall-plane 会把 12 栏图样打破（块高不再恒定，纵向搬块就会抖）。 */
html[data-theme] .folia-wall-plane > #homeRecommended {
  grid-template-columns: repeat(12, minmax(0, 1fr)) !important;
  grid-auto-rows: calc((100cqw - 22px) / 12) !important;
}
/* 900 以下不再让 12 列槽位挤进 4 列（那会变成一条条全宽横带）：
   改成真正的两栏/三栏海报流，按卡片宽度给 3:4 或 16:9，行高交给内容自己算。
   断点跟底栏导航一致（900）：这个宽度起底栏接管导航，浮动侧栏要收起来。 */
@media (max-width: 900px) {
  html[data-theme] .sidebar { display: none !important; }
  html[data-theme] .ledger-search { width: calc(100vw - 100px); }
  html[data-theme] .dock { width: calc(100vw - 32px); left: 50%; }
  html[data-theme] #homeRecommended {
    grid-template-columns: 1fr 1fr 1fr;
    grid-auto-rows: auto;
    grid-auto-flow: dense;
    align-items: start;
    /* 顶上给悬浮搜索胶囊让出 76px：原来从 y=0 起铺，第一排海报被搜索框压住半张 */
    padding: 76px 0 168px;
  }
  html[data-theme] #homeRecommended .pod-card:not(.is-peek):not(.is-playing-tile) {
    grid-column: span 1 !important;
    grid-row: auto !important;
    height: auto !important;
    aspect-ratio: 3 / 4;
  }
  html[data-theme] #homeRecommended .pod-card:not(.is-peek):not(.is-playing-tile):nth-child(7n + 1) {
    grid-column: span 2 !important;
    aspect-ratio: 16 / 9;
  }
  html[data-theme] #homeRecommended .pod-card.is-peek,
  html[data-theme] #homeRecommended .pod-card.is-playing-tile {
    grid-column: span 2 !important;
    grid-row: auto !important;
    height: auto !important;
    aspect-ratio: 1 / 1;
  }
  html[data-theme] #homeRecommended .pod-card .pod-card-main { padding: 12px 12px 13px; gap: 4px; }
  html[data-theme] #homeRecommended .pod-card .pod-card-main > strong {
