    -webkit-line-clamp: 2;
  }
  html[data-theme] #homeRecommended .pod-card:nth-child(7n + 1) .pod-card-main > strong {
    font-size: clamp(22px, 6.4vw, 34px);
  }
}
@media (max-width: 600px) {
  html[data-theme] #homeRecommended { grid-template-columns: 1fr 1fr !important; }
}

/* 这里不要再写 `.decor-idle { animation: none !important }`。
   取消掉入场动画后，回前台时动画会被重新挂上，整页从 opacity:0 重播一遍，
   看起来就是"点一下别的窗口，我的应用闪一下"。后台落回终态改由
   13-theme.js 的 settleAnimations() 用 finish() 完成，它不会触发重播。 */

@media (prefers-reduced-motion: reduce) {
  html[data-theme] .pod-card,
  html[data-theme] .nav button { transition: none; }
  html[data-theme] .page.active,
  html[data-theme] #page-podcast .show-hero,
  html[data-theme] #page-podcast .show-hero .pod-art,
  html[data-theme] #page-podcast .page-head > div > .eyebrow,
  html[data-theme] #page-podcast .page-head h1,
  html[data-theme] #page-podcast .page-head .subtitle,
  html[data-theme] #page-podcast .detail-actions,
  html[data-theme] #page-podcast .ep-row,
  html[data-theme] #homeRecommended .pod-card,
  html[data-theme] .reader,
  html[data-theme] #transcript .cue,
  html[data-theme] .dock { animation: none !important; }
}

html[data-theme] ::selection { background: color-mix(in srgb, var(--accent) 32%, transparent); color: var(--ink); }

/* ==========================================================================
   10. 视觉精修 v2：侧栏拆成独立玻璃胶囊；底栏改成两行式播放器
   依据 Refactoring UI：先分层级，再收间距，最后才是材质与阴影。
   - 侧栏不再是一根 640px 高的黑柱，品牌与两组导航各自成块
   - 选中态用奶油实心圆，和底栏主按钮同一套语言；珊瑚只留给进度与强调
   - 底栏从“顶部一根进度线的黑板”改成“信息行 + 时间轴行”
   ========================================================================== */

/* ---------- 10.1 侧栏：品牌 + 两组胶囊 ---------- */
