html[data-theme] #homeRecommended .tile-live-lyric .tl-label { color: var(--tl-fg-dim, rgba(255, 255, 255, 0.32)); }
html[data-theme] #homeRecommended .tile-live-lyric .tl-word.past { color: var(--tl-fg, rgba(255, 255, 255, 0.96)); }
/* 逐词高亮：底色和字色由脚本按这个词身后的封面亮度选（深底白字 / 主题色深字），
   不再固定「30% 主题色 + 白字」——压在 SmartLess 那种米色海报上会糊成一块。 */
html[data-theme] #homeRecommended .tile-live-lyric .tl-word.on {
  color: var(--tl-hl-ink, #fff);
  background: var(--tl-hl-bg, color-mix(in srgb, var(--accent) 30%, transparent));
  box-shadow: 0 0 0 2px var(--tl-hl-ring, color-mix(in srgb, var(--accent) 30%, transparent));
  border-radius: 3px;
  text-shadow: var(--tl-hl-glow, 0 0 18px color-mix(in srgb, var(--accent) 55%, transparent));
}

/* 播放瓦片右上角的「全屏封面」小钮 */
html[data-theme] #homeRecommended .pod-card.is-playing-tile .tile-full {
  position: absolute;
  z-index: 12;
  top: 14px;
  right: 14px;
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.58);
  backdrop-filter: blur(10px);
  color: var(--ink);
  cursor: pointer;
  opacity: 0.82;
  transition: opacity var(--motion-fast) var(--ease), background-color var(--motion-fast) var(--ease), scale var(--motion-fast) var(--ease);
}
html[data-theme] #homeRecommended .pod-card.is-playing-tile .tile-full:hover { opacity: 1; background: var(--accent); color: #0a0a0a; }
html[data-theme] #homeRecommended .pod-card.is-playing-tile .tile-full:active { scale: 0.92; }
html[data-theme] #homeRecommended .pod-card.is-playing-tile .tile-full svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; }

/* ---------- 14. 封面全屏 ---------- */
html[data-theme] .cover-stage {
  position: fixed;
  inset: 0;
  z-index: 95;
  display: none;
  place-items: center;
  width: 100%;
  height: 100%;
  max-width: none;
  max-height: none;
  margin: 0;
  padding: 0;
  border: 0;
  background: #040406;
  color: var(--ink);
  opacity: 0;
  transition: opacity 0.24s var(--ease);
  overflow: hidden;
  isolation: isolate;
}
html[data-theme] .cover-stage[open] { display: grid; }
html[data-theme] .cover-stage:modal { overscroll-behavior: contain; }
html[data-theme] .cover-stage::backdrop {
  overflow: hidden;
  overscroll-behavior: contain;
  background: transparent;
}
html[data-theme] .cover-stage.on { opacity: 1; }
html[data-theme] .cs-backdrop { position: absolute; inset: 0; z-index: 0; }
/* 封面已经 object-fit:cover 铺满整屏，底下那层 60px 模糊等于白算一整屏；直接不画 */
html[data-theme] .cs-bg { display: none; }
/* 全屏舞台的压暗照瓦片展开态（Folia 的 `.lattice-poster-shade`）：不再是整屏一条
   竖向黑幕把底下 84% 全压黑，而是「底 + 左」两段复合渐变——左下这块暗区托住标题，
   右上是封面本身；顶上加一条很浅的横向条，只为了让关闭按钮在亮封面上也看得清。 */
html[data-theme] .cover-stage::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  background:
    linear-gradient(0deg,
      rgba(0, 0, 0, 0.88) 0%,
      rgba(0, 0, 0, 0.64) 14%,
      rgba(0, 0, 0, 0.34) 34%,
      rgba(0, 0, 0, 0.12) 50%,
      rgba(0, 0, 0, 0) 62%),
    linear-gradient(90deg,
      rgba(0, 0, 0, 0.72) 0%,
      rgba(0, 0, 0, 0.38) 34%,
      rgba(0, 0, 0, 0.08) 68%,
      rgba(0, 0, 0, 0) 100%),
    linear-gradient(180deg,
      rgba(0, 0, 0, 0.36) 0%,
      rgba(0, 0, 0, 0) 13%);
}
html[data-theme] .cs-img {
  position: absolute;
  inset: 0;
  z-index: 2;
  width: 100%;
  height: 100%;
  max-width: none;
  max-height: none;
  object-fit: cover;
  object-position: center;
  border-radius: 0;
  box-shadow: none;
  opacity: 0;
  transform: scale(1.02);
  transition: opacity 0.3s var(--ease), transform 0.42s cubic-bezier(0.2, 0.9, 0.2, 1);
}
html[data-theme] .cover-stage.on .cs-img { opacity: 1; transform: none; }
html[data-theme] .cs-close {
  position: absolute;
  z-index: 4;
  top: 22px;
  right: 22px;
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 999px;
  background: rgba(18, 18, 21, 0.72);
  backdrop-filter: blur(16px);
  color: var(--ink);
  cursor: pointer;
  transition: background-color var(--motion-fast) var(--ease), scale var(--motion-fast) var(--ease);
}
html[data-theme] .cs-close:hover { background: var(--accent); color: #0a0a0a; }
html[data-theme] .cs-close:active { scale: 0.92; }
html[data-theme] .cs-close svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.9; }
html[data-theme] .cs-copy {
  position: absolute;
  z-index: 4;
  left: clamp(24px, 4vw, 56px);
  right: clamp(24px, 4vw, 56px);
  bottom: clamp(26px, 6vh, 64px);
  pointer-events: none;
}
html[data-theme] .cs-kicker,
html[data-theme] .cs-copy h2,
html[data-theme] .cs-copy p { text-shadow: 0 2px 24px rgba(0, 0, 0, 0.70); }
html[data-theme] .cs-kicker {
  font: 800 11px/1 var(--sans);
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--accent);
}
html[data-theme] .cs-copy h2 {
  margin: 10px 0 0;
  max-width: 76vw;
  font: 800 clamp(30px, 4vw, 64px)/0.98 var(--sans);
  letter-spacing: -0.045em;
  color: var(--ink);
  text-wrap: balance;
}
html[data-theme] .cs-copy p {
  margin: 10px 0 0;
  font: 600 12px/1.4 var(--sans);
  letter-spacing: 0.02em;
  color: rgba(247, 244, 238, 0.56);
}
/* 播放中用封面全屏时，标题让到左上角，底部整块留给字幕 */
html[data-theme] .cover-stage.lyric-on .cs-copy {
  top: clamp(20px, 3vh, 34px);
  bottom: auto;
  right: auto;
  max-width: min(540px, 56vw);
}
html[data-theme] .cover-stage.lyric-on .cs-copy h2 {
  margin-top: 6px;
  font-size: clamp(17px, 1.9vw, 28px);
  line-height: 1.04;
  letter-spacing: -0.035em;
}
html[data-theme] .cover-stage.lyric-on .cs-copy p { margin-top: 6px; font-size: 11px; }
/* 封面源被外站防盗链挡住时，用主题色和一档深底兜住整块窗口，别让全屏只剩纯黑。 */
html[data-theme] .cover-stage.cover-empty {
  background:
    radial-gradient(120% 90% at 18% 12%, color-mix(in srgb, var(--accent) 34%, transparent), transparent 62%),
    radial-gradient(90% 80% at 88% 96%, color-mix(in srgb, var(--accent2) 18%, transparent), transparent 58%),
    linear-gradient(158deg, #1b1410, #050506 68%);
}
html[data-theme] .cover-stage.cover-empty .cs-img,
html[data-theme] .cover-stage.cover-empty .cs-bg { opacity: 0; }
html[data-theme] .cs-lyric {
  position: absolute;
  z-index: 4;
  left: 50%;
  bottom: clamp(44px, 8vh, 96px);
  width: min(980px, 84vw);
  display: flex;
  flex-direction: column;
  gap: 7px;
  text-align: center;
  pointer-events: none;
  opacity: 0;
  translate: -50% 10px;
  transition: opacity 0.3s var(--ease), translate 0.42s var(--ease);
  /* 与瓦片同一套：固定字号 + 超长句整块上移，不裁字 */
  transform: translateY(calc(-1 * var(--tl-shift, 0px)));
}
html[data-theme] .cover-stage.lyric-on .cs-lyric { opacity: 1; translate: -50% 0; }
html[data-theme] .cs-lyric .tl-line {
  display: block;
  flex: 0 0 auto;
  position: relative;
  z-index: 1;
  white-space: normal;
  overflow-wrap: break-word;
  font: 600 var(--tl-fs, clamp(20px, 2.35vw, 34px))/1.34 var(--sans);
  letter-spacing: -0.018em;
  color: var(--tl-fg-dim, rgba(255, 255, 255, 0.62));
  text-shadow: var(--tl-shadow, 0 0 1px rgba(0, 0, 0, 0.92), 1px 1px 0 rgba(0, 0, 0, 0.88),
    -1px 1px 0 rgba(0, 0, 0, 0.88), 1px -1px 0 rgba(0, 0, 0, 0.88), -1px -1px 0 rgba(0, 0, 0, 0.88),
    0 2px 10px rgba(0, 0, 0, 0.45));
}
html[data-theme] .cs-lyric .tl-cur {
  margin: 2px 0;
  font-weight: 800;
  line-height: 1.34;
  letter-spacing: -0.03em;
  color: var(--tl-fg, rgba(255, 255, 255, 0.94));
}
html[data-theme] .cs-lyric .tl-word { transition: color 0.16s linear, background-color 0.16s linear, text-shadow 0.16s linear; }
html[data-theme] .cs-lyric .tl-word.past { color: var(--tl-fg, #fff); }
html[data-theme] .cs-lyric .tl-word.on {
  color: var(--tl-hl-ink, #08080a);
  background: var(--tl-hl-bg, var(--accent));
  box-shadow: 0 0 0 3px var(--tl-hl-ring, var(--accent));
  border-radius: 4px;
  text-shadow: none;
}
html[data-theme] .cs-lyric .tl-label { color: var(--tl-fg-dim, rgba(255, 255, 255, 0.36)); }

/* ---------- 15. 壁纸：Folia 的歌词模式 ---------- */
/* 底子不是棕色渐变了，而是封面本身：模糊、压暗、留一团主题色光。
   歌词是主体，标题只是页脚；颜色只从 --accent 来。 */
html[data-theme] .wallpaper { background: #050506; color: #f7f4ee; }
html[data-theme] .wp-bg {
  filter: blur(46px) saturate(1.06) brightness(0.36);
  opacity: 0.94;
}
html[data-theme] .wp-shade {
  background:
    radial-gradient(62% 58% at 72% 22%, color-mix(in srgb, var(--accent) 14%, transparent), transparent 68%),
    linear-gradient(90deg, rgba(4, 4, 6, 0.94) 0%, rgba(6, 6, 9, 0.78) 44%, rgba(8, 8, 11, 0.62) 74%, rgba(4, 4, 6, 0.90) 100%),
    linear-gradient(0deg, rgba(3, 3, 5, 0.88), transparent 46%);
}
html[data-theme] .wp-shade::after {
  background: radial-gradient(58% 48% at 64% 58%, color-mix(in srgb, var(--accent) 9%, transparent), transparent 72%);
}
html[data-theme] .wp-kicker { color: var(--accent); }
html[data-theme] .wp-title { color: #f7f4ee; }
html[data-theme] .wp-cue.past,
html[data-theme] .wp-cue.future { color: rgba(247, 244, 238, 0.80); }
html[data-theme] .wp-cue.active::before {
  background: var(--accent);
  box-shadow: 0 0 30px color-mix(in srgb, var(--accent) 34%, transparent);
}
html[data-theme] .wp-cue.active .wp-en { color: #fff8ec; }
html[data-theme] .wp-label { color: rgba(247, 244, 238, 0.46); }
html[data-theme] .wp-word.active {
  color: #fff;
  background-image: linear-gradient(180deg, transparent 57%, color-mix(in srgb, var(--accent) 34%, transparent) 57%, color-mix(in srgb, var(--accent) 18%, transparent) 94%, transparent 94%);
  text-shadow: 0 0 22px color-mix(in srgb, var(--accent) 46%, transparent);
}
html[data-theme] .wp-zh { color: rgba(247, 244, 238, 0.60); }
html[data-theme] .wpbtn {
  border-color: rgba(255, 255, 255, 0.15);
  background: rgba(10, 10, 13, 0.58);
  color: rgba(247, 244, 238, 0.82);
}
html[data-theme] .wpbtn:hover {
  border-color: color-mix(in srgb, var(--accent) 62%, transparent);
  background: color-mix(in srgb, var(--accent) 18%, rgba(255, 255, 255, 0.06));
  color: #fff;
}

/* 字号：只改歌词，标题与前后句跟着缩放，版式不被打散 */
html[data-theme] .wallpaper { --wp-active-size: clamp(30px, 3.7vw, 76px); --wp-side-size: clamp(14px, 1.45vw, 28px); }
html[data-theme] .wallpaper[data-wpsize="s"] { --wp-active-size: clamp(24px, 2.6vw, 46px); --wp-side-size: clamp(12px, 1.2vw, 22px); }
html[data-theme] .wallpaper[data-wpsize="l"] { --wp-active-size: clamp(34px, 4.6vw, 92px); --wp-side-size: clamp(16px, 1.7vw, 32px); }
html[data-theme] .wallpaper .wp-cue.active .wp-en { font-size: var(--wp-active-size); }
html[data-theme] .wallpaper .wp-cue.past,
html[data-theme] .wallpaper .wp-cue.future { font-size: var(--wp-side-size); }
/* 对齐：默认左对齐带竖条；居中时去掉竖条，文字居中 */
html[data-theme] .wallpaper[data-wpalign="center"] .wp-cue { padding-left: 0; text-align: center; }
html[data-theme] .wallpaper[data-wpalign="center"] .wp-cue.active::before { display: none; }
/* 背景：封面 / 深色 / 纯黑 */
html[data-theme] .wallpaper[data-wpshade="deep"] .wp-bg { filter: blur(58px) saturate(1.04) brightness(0.16); }
html[data-theme] .wallpaper[data-wpshade="deep"] .wp-shade { background: linear-gradient(90deg, rgba(3, 3, 5, 0.96), rgba(4, 4, 6, 0.90) 60%, rgba(2, 2, 4, 0.97)); }
html[data-theme] .wallpaper[data-wpshade="plain"] .wp-bg { display: none; }
html[data-theme] .wallpaper[data-wpshade="plain"] .wp-shade { background: #000; }
html[data-theme] .wallpaper[data-wpshade="plain"] .wp-shade::after { display: none; }
/* 标题可隐藏：只剩歌词，画面更干净 */
html[data-theme] .wallpaper[data-wptitle="off"] .wp-kicker,
html[data-theme] .wallpaper[data-wptitle="off"] .wp-title { display: none; }
html[data-theme] .wallpaper[data-wptitle="off"] .wp-content { padding-top: clamp(22px, 4vh, 46px); }

/* 样式面板：贴着控制条浮起来，不再另开一页 */
html[data-theme] .wp-style {
  position: absolute;
  z-index: 8;
  right: clamp(20px, 4vw, 54px);
  bottom: calc(clamp(20px, 4vh, 42px) + 54px);
  width: 286px;
  padding: 14px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 16px;
  background: rgba(12, 12, 15, 0.92);
  box-shadow: 0 24px 70px -20px rgba(0, 0, 0, 0.92), inset 0 1px 0 rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(22px) saturate(1.1);
  color: var(--ink);
  animation: wpStyleIn 0.22s var(--ease) both;
}
html[data-theme] .wp-style[hidden] { display: none; }
@keyframes wpStyleIn {
  from { opacity: 0; transform: translateY(8px) scale(0.985); }
  to { opacity: 1; transform: none; }
}
html[data-theme] .wp-style .wps-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 2px 10px;
  margin-bottom: 4px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
  font: 800 11px/1 var(--sans);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(247, 244, 238, 0.54);
}
html[data-theme] .wp-style .wps-head button {
  border: 0;
  background: none;
  color: color-mix(in srgb, var(--accent) 76%, #fff);
  font: 600 11px/1 var(--sans);
  letter-spacing: 0.02em;
  cursor: pointer;
  padding: 4px 2px;
}
html[data-theme] .wp-style .wps-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 8px 2px;
}
html[data-theme] .wp-style .wps-row > span { font: 600 11.5px/1 var(--sans); color: rgba(247, 244, 238, 0.66); }
html[data-theme] .wp-style .wps-seg {
  display: flex;
  gap: 2px;
  padding: 2px;
  border: 1px solid rgba(255, 255, 255, 0.055);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.045);
}
html[data-theme] .wp-style .wps-seg button {
  min-width: 34px;
  height: 25px;
  padding: 0 8px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: rgba(247, 244, 238, 0.52);
  font: 600 11px/1 var(--sans);
  cursor: pointer;
  transition: background-color var(--motion-fast) var(--ease), color var(--motion-fast) var(--ease);
}
html[data-theme] .wp-style .wps-seg button:hover { color: var(--ink); background: rgba(255, 255, 255, 0.07); }
html[data-theme] .wp-style .wps-seg button.is-on { background: var(--accent); color: #0a0a0a; font-weight: 700; }

/* ==========================================================================
   9. 一致性修补（整站 UI 巡检后的统一层）
   只改观感，不动交互：卡片表面 / 播客库塌陷 / 瓦片压字 / 阅读页顶栏 /
   单集行密度 / 收听模式与笔记的列宽 / 单集简介行宽。
   ========================================================================== */

/* 9.1 卡片表面：4.5% 的白在近黑底上几乎看不见边界，抬到 5.5% 并提亮描边 */
html[data-theme] .card {
  background: rgba(255, 255, 255, 0.055);
  border-color: rgba(255, 255, 255, 0.085);
}

/* 9.2 播客库：主题里没有给 .pod-grid 网格，而 .pod-card 是 height:100%，
      父级高度自动时整排卡片塌成 0 高 —— 15 档订阅在页面上只剩一个空框。
      这里补一套和首页同语言的方形海报网格，铺满卡面（负边距抵掉卡内留白）。 */
html[data-theme] #page-library .card { overflow: hidden; }
html[data-theme] #page-library .pod-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(196px, 1fr));
  gap: 2px;
  margin: 16px -18px -18px;
}
html[data-theme] #page-library .pod-card { height: auto; aspect-ratio: 1 / 1; }
html[data-theme] #page-library .pod-card .pod-card-main { padding: 14px 14px 12px; }
html[data-theme] #page-library .pod-card .pod-card-main > strong {
  font-size: clamp(17px, 1.5vw, 21px);
  line-height: 1.05;
  -webkit-line-clamp: 2;
}
html[data-theme] #page-library .pod-card .pod-meta { font-size: 11px; }

/* 9.3 首页瓦片：封面底色浅的节目（浅蓝/浅黄海报）上白字发虚，
      加深底部压字黑幕并给标题一层贴地阴影 */
html[data-theme] #homeRecommended .pod-card::after {
  background: linear-gradient(180deg,
    rgba(0, 0, 0, 0.04) 28%,
    rgba(0, 0, 0, 0.34) 52%,
    rgba(0, 0, 0, 0.96) 100%);
}
html[data-theme] #homeRecommended .pod-card .pod-card-main > strong {
  text-shadow: 0 1px 1px rgba(0, 0, 0, 0.45), 0 10px 34px rgba(0, 0, 0, 0.55);
}

/* 9.4 阅读页：顶栏原来是一层透明胶囊，正文滚到顶部就从按钮背后穿过去
      （"精听" 按钮压住 09:53 的时间码）。给顶栏补实底 + 下沿渐隐。 */
html[data-theme] .reader-top-actions {
  background: linear-gradient(180deg,
    #08080a 0%,
    #08080a 62%,
    rgba(8, 8, 10, 0.72) 78%,
    rgba(8, 8, 10, 0) 100%);
  border-bottom: 0;
  box-shadow: none;
}
/* 当前句同时挂了 base 的紫色渐变竖条和主题的珊瑚内描边，左边出现两根相邻的线；
   留珊瑚那根，紫色那根收掉 */
html[data-theme] .cue.active::before,
html[data-theme] .cue.is-active::before { opacity: 0; }

/* 9.5 单集行：标题 24px 比 44px 的封面重得多，一行 143px 只放一条，
      历史/节目页都显得笨重。收成 19–20px、46px 封面、圆角小按钮。 */
html[data-theme] #page-podcast .ep-row,
html[data-theme] .ledger-rows .ep-row { min-height: 0; padding: 10px 4px; gap: 14px; }
html[data-theme] #page-podcast .ep-row .ep-art,
html[data-theme] .ledger-rows .ep-art {
  width: 46px;
  height: 46px;
  flex: 0 0 46px;
  border-radius: 6px;
}
html[data-theme] #page-podcast .ep-row .ep-title {
  font: 700 19px/1.32 var(--sans);
  letter-spacing: -0.02em;
}
html[data-theme] .ledger-rows .ep-title {
  font: 700 20px/1.32 var(--sans);
  letter-spacing: -0.02em;
  display: block;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  -webkit-line-clamp: none;
}
html[data-theme] #page-podcast .ep-row .ep-sub,
html[data-theme] .ledger-rows .ep-sub { font-size: 12px; color: rgba(247, 244, 238, 0.55); }
html[data-theme] .ledger-rows .ep-dur {
  font: 500 12px/1 var(--mono);
  min-width: 64px;
  text-align: right;
  color: rgba(247, 244, 238, 0.55);
}
html[data-theme] #page-podcast .ep-row .mini-btn,
html[data-theme] .ledger-rows .mini-btn {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: inline-grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.05);
  color: rgba(247, 244, 238, 0.6);
}
html[data-theme] #page-podcast .ep-row .mini-btn:hover,
html[data-theme] .ledger-rows .mini-btn:hover {
  background: rgba(255, 255, 255, 0.12);
  color: var(--ink);
}

/* 9.6 收听模式：界面只有 2 张卡、播完之后有 3 张，同一个两列网格下
      第三张永远孤零零占半行。按子项数量切换列数：2 张两列、3 张三列。 */
html[data-theme] .listen-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
html[data-theme] .listen-grid:has(> :nth-child(3)) {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

/* 9.7 笔记：两栏原来是 1fr / .9fr（552 / 497），左右不齐；改等宽两列 */
html[data-theme] .notes-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }

/* 9.8 单集页简介：正文跑满 1000px、一行近百字符，读到一半就丢行；
      收到 66ch 并压低字号/行距，长文才读得下去 */
html[data-theme] #page-episode .ep-desc {
  max-width: 66ch;
  font-size: 15.5px;
  line-height: 1.75;
  color: rgba(247, 244, 238, 0.66);
}

/* 9.9 历史/收藏这类 .anim-list 列表没走 #page-podcast 的规则，
      标题还是 26px、行高 143px。统一收成 19px + 46px 封面。 */
html[data-theme] .anim-list .ep-row { min-height: 0; padding: 10px 4px; gap: 14px; }
html[data-theme] .anim-list .ep-art {
  width: 46px;
  height: 46px;
  flex: 0 0 46px;
  border-radius: 6px;
}
html[data-theme] .anim-list .ep-title {
  font: 700 19px/1.32 var(--sans);
  letter-spacing: -0.02em;
  display: block;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  -webkit-line-clamp: none;
}
html[data-theme] .anim-list .ep-sub { font-size: 12px; color: rgba(247, 244, 238, 0.55); }

/* 9.10 空态卡片：主题把带 .empty-line 的 .card 剥成了透明壳，
      结果页面上只剩一行字飘在虚空里（笔记右栏、书签、收藏、队列）。
      保留卡片表面，空态文案上下多留点空气。 */
html[data-theme] .card:has(.empty-line) {
  padding: 18px;
  border: 1px solid rgba(255, 255, 255, 0.085);
  background: rgba(255, 255, 255, 0.05);
  box-shadow: none;
}
html[data-theme] .empty-line { padding: 44px 12px; }

/* 9.11 下载管理：节目头和它的单集都从卡片左内边距起排，
      单集看起来像节目名而不是从属项。把单集行缩到节目名下面，
      节目之间补一条分隔，层级才立得住。 */
html[data-theme] #page-downloads .qrow { padding-left: 56px; }
html[data-theme] #page-downloads .dl-pod-head { padding-bottom: 2px; }
html[data-theme] #page-downloads .dl-pod + .dl-pod {
  margin-top: 4px;
  padding-top: 8px;
  border-top: 1px solid rgba(255, 255, 255, 0.07);
}

/* ---------- 10. 发现页 / 设置页 精修 ---------- */

/* 10.1 发现页页签：三个词挤在一起、字号比正文还小，拉开间距并统一字重 */
html[data-theme] #page-discover .tabs { gap: 26px; }
html[data-theme] #page-discover .tabs button {
  padding: 2px 0 12px;
  font: 600 13px/1 var(--sans);
  letter-spacing: 0.02em;
  color: rgba(247, 244, 238, 0.55);
}
html[data-theme] #page-discover .tabs button.active { color: var(--accent); }

/* 10.2 榜单行：排名占了一整列空白（数字在 186、封面在 230），
      标题 17px 却配 54px 封面。排名收成 26px 窄列，行内边距和封面一起收一点。 */
html[data-theme] #page-discover .chart-rank {
  flex: 0 0 26px;
  width: 26px;
  font: 600 12px/1 var(--mono);
  color: rgba(247, 244, 238, 0.38);
}
html[data-theme] #page-discover .online-row { padding: 9px 4px; gap: 12px; }
html[data-theme] #page-discover .online-art {
  width: 52px;
  height: 52px;
  flex: 0 0 52px;
  border-radius: 6px;
}
html[data-theme] #page-discover .online-title {
  font: 700 16.5px/1.35 var(--sans);
  letter-spacing: -0.01em;
}
/* 悬停原来是整行标题变珊瑚红，看着像出错；改成提亮到正白 */
html[data-theme] #page-discover .online-row:hover .online-title { color: var(--ink); }
html[data-theme] #page-discover .online-sub { font-size: 12.5px; color: rgba(247, 244, 238, 0.5); }

/* 10.3 右侧「订阅」：一列 50 个实心珊瑚按钮，红成一面墙。
      改成描边款，只在悬停时填色 —— 一屏里只留真正的主动作是实心。 */
html[data-theme] #page-discover .online-actions .btn.primary {
  height: 30px;
  padding: 0 13px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 999px;
  background: transparent;
  color: rgba(247, 244, 238, 0.72);
  font: 600 12px/1 var(--sans);
  box-shadow: none;
}
html[data-theme] #page-discover .online-actions .btn.primary:hover {
  border-color: var(--accent);
  background: var(--accent);
  color: #fff;
}

/* 10.4 设置左菜单：11 项每项 60px 高、字只有 17px，整栏比右侧内容还高，
      滚起来还会跑掉。收成 38px 一项，整栏吸顶。 */
html[data-theme] .settings-menu {
  align-self: start;
  position: sticky;
  top: 26px;
  padding: 8px;
}
html[data-theme] .settings-menu button {
  height: 38px;
  padding: 0 12px;
  border-radius: 8px;
  font: 600 13.5px/1 var(--sans);
  color: rgba(247, 244, 238, 0.64);
}
html[data-theme] .settings-menu button:hover {
  background: rgba(255, 255, 255, 0.05);
  color: var(--ink);
}
html[data-theme] .settings-menu button.active {
  background: rgba(255, 255, 255, 0.075);
  color: var(--ink);
  box-shadow: inset 2px 0 0 var(--accent);
}

/* 10.5 设置行：说明文字有整行 1090px 长（单流播放、跳过级别那两行），
      把行撑到 100px 还读不下去。说明收到 66ch、字号降一档，行高回到 60px 上下。 */
html[data-theme] .setting-row { padding: 13px 2px; align-items: center; gap: 24px; }
html[data-theme] .setting-row > div { min-width: 0; }
html[data-theme] .setting-row > div > strong { font: 700 15px/1.3 var(--sans); letter-spacing: -0.01em; }
html[data-theme] .setting-row > div > p {
  margin: 5px 0 0;
  max-width: 66ch;
  font: 500 12.5px/1.55 var(--sans);
  color: rgba(247, 244, 238, 0.52);
}
html[data-theme] .setting-row > select,
html[data-theme] .setting-row > .btn {
  flex: 0 0 auto;
  height: 32px;
  padding: 0 11px;
  border-radius: 8px;
  font-size: 12.5px;
}
html[data-theme] .setting-row > button.switch { flex: 0 0 auto; }

/* 10.6 发现页的取数失败提示：原来是一整条 109px 的浅色横带，文字在上、
      重试在下，把榜单整体往下顶一屏。收成一行提示条：文字 + 重试并排。 */
html[data-theme] #page-discover .online-state.err {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 0;
  margin: 10px 0 8px;
  padding: 12px 16px;
  border: 1px solid rgba(253, 92, 71, 0.18);
  border-radius: 8px;
  background: rgba(253, 92, 71, 0.06);
  font-size: 12.5px;
}

/* ---------- 11. 节目详情页 精修 ---------- */

/* 11.1 页头（eyebrow/标题/副行）原来按 `top: 54vh-150px` 叠在封面里，
      但封面底部还有一列 flex-end 的主按钮（播放最新/已订阅），
      副行底边 421 正好压到按钮顶边 417 —— 肉眼看就是「文字贴着按钮」。
      把页头整体上提 26px，给两者留出呼吸；封面高度不动。 */
html[data-theme] #page-podcast .page-head { top: calc(54vh - 176px); }

/* 11.1b 封面本身是低清方图铺满宽屏，放大后颗粒很重；2.5px 柔化 + 轻微压暗，
       让它退成氛围背景，标题保持锐利。 */
html[data-theme] #page-podcast .show-hero .pod-art img {
  filter: blur(2.5px) saturate(1.08) brightness(0.88);
  transform: scale(1.03);
}

/* 11.2 副行（634 集 · 双语词级文字稿）是 13px/650 的实心灰，压在大标题下面有点抢；
      降半档、拉开字距，让它退成注脚 */
html[data-theme] #page-podcast .page-head .subtitle {
  margin-top: 10px;
  font: 600 12.5px/1.4 var(--sans);
  letter-spacing: 0.06em;
  color: rgba(247, 244, 238, 0.62);
}

/* 11.3 「单集 / 最近 20 / 加载全部单集」原来被 space-between 三等分，
      计数那行飘在卡片正中。计数靠右，紧挨按钮。 */
html[data-theme] #page-podcast .section-title { gap: 12px; }
html[data-theme] #page-podcast .section-title small {
  margin-left: auto;
  font: 500 11.5px/1 var(--mono);
  letter-spacing: 0.02em;
  color: rgba(247, 244, 238, 0.45);
}

/* 11.4 筛选胶囊：选中态原来和「播放最新」一样是实心珊瑚，一屏里两个主按钮。
      选中改成珊瑚描边 + 淡底，实心只留给播放。 */
html[data-theme] #page-podcast .ep-filter-row button { height: 26px; padding: 0 11px; font-size: 11.5px; }
html[data-theme] #page-podcast .ep-filter-row button.on {
  background: color-mix(in srgb, var(--accent) 15%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent) 38%, transparent);
  color: var(--accent);
}

/* 11.5 单集行：悬停时标题整行变珊瑚红（看着像报错），改成正白；
      右侧时长/两个小按钮太淡，时长右对齐成一列，按钮补一圈可见的底 */
html[data-theme] #page-podcast .ep-row:hover .ep-title { color: var(--ink); }
html[data-theme] #page-podcast .ep-dur {
  min-width: 62px;
  text-align: right;
  font: 500 11.5px/1 var(--mono);
  color: rgba(247, 244, 238, 0.42);
}
html[data-theme] #page-podcast .ep-actions { gap: 4px; }
html[data-theme] #page-podcast .ep-row .mini-btn {
  width: 28px;
  height: 28px;
  background: rgba(255, 255, 255, 0.07);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.08);
  color: rgba(247, 244, 238, 0.72);
  font-size: 12px;
}
html[data-theme] #page-podcast .ep-row .mini-btn:hover {
  background: color-mix(in srgb, var(--accent) 18%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 44%, transparent);
  color: var(--accent);
}

/* 11.6 节目预览弹窗（发现页点一行会先弹这个「节目详情」）：
      卡片被自动聚焦，浏览器画出 2px 珊瑚描边，远看像报错框；
      卡片背景只有 4% 白、盖在暗遮罩上发灰发浊；
      简介 12.5px 撑满 559px，四行长文没有阅读宽度。 */
html[data-theme] .modal-card:focus,
html[data-theme] .modal-card:focus-visible { outline: 0; }
html[data-theme] .modal-card {
  padding: 22px 24px 20px;
  border: 1px solid rgba(255, 255, 255, 0.10);
  border-radius: 14px;
  background: #141417;
  box-shadow: 0 44px 110px -46px #000;
}
html[data-theme] .modal-card .online-detail-hero > .pod-art,
html[data-theme] .modal-card .online-detail-hero > img { border-radius: 8px; }
html[data-theme] .modal-card .online-detail-desc {
  max-width: 62ch;
  font-size: 13px;
  line-height: 1.75;
  color: rgba(247, 244, 238, 0.64);
}



/* ---------- 12. 空态/卡片里的 ghost 按钮 ----------
   卡片表面只有 5% 白，「去设置 / 去播客库」这类 ghost 按钮的字色原本 55% 白，
   压在卡上算出来 1.9:1，看起来像一行注释而不是按钮。抬到 70%，并保留悬停转白。 */
html[data-theme] .btn.ghost { color: rgba(247, 244, 238, 0.70); }
html[data-theme] .btn.ghost:hover { color: var(--ink); }
/* 高亮块要「一出现就是清楚的」：字在词与词之间切换时若走 160ms 颜色过渡，
   那 160ms 里底色和字色都停在半路（白字压半透明珊瑚），正好是最看不清的一瞬。
   所以只给 on 这一档去掉过渡，past 仍保留淡出。 */
html[data-theme] #homeRecommended .tile-live-lyric .tl-word.on,
html[data-theme] .cs-lyric .tl-word.on { transition: none; }
